        FCB     $00,$00,$00,$00,$00,$00,$00,$00,$07,$F0,$0C,$18,$0C,$00,$0C,$00
        FCB     $0C,$18,$07,$F0,$00,$00,$00,$00,$00,$00,$00,$00,$0F,$F0,$06,$18
        FCB     $06,$18,$06,$18,$06,$18,$0F,$F0,$00,$00,$00,$00,$00,$00,$00,$00
        FCB     $0F,$F8,$06,$18,$07,$80,$06,$00,$06,$18,$0F,$F8,$00,$00,$00,$00
        FCB     $00,$00,$00,$00,$07,$F0,$0C,$00,$0C,$78,$0C,$18,$0C,$18,$07,$F0
        FCB     $00,$00,$00,$00,$00,$00,$00,$00,$0F,$1E,$06,$0C,$07,$FC,$06,$0C
        FCB     $06,$0C,$0F,$1E,$00,$00,$00,$00,$00,$00,$00,$00,$03,$F0,$00,$C0
        FCB     $00,$C0,$00,$C0,$00,$C0,$03,$F0,$00,$00,$00,$00,$00,$00,$00,$00
        FCB     $01,$FC,$00,$18,$00,$18,$00,$18,$0C,$18,$07,$F0,$00,$00,$00,$00
