        FCB     $06,$0C,$06,$0C,$03,$18,$01,$F0,$00,$00,$00,$00,$00,$00,$00,$00
        FCB     $0F,$F0,$06,$18,$07,$F0,$06,$C0,$06,$60,$0F,$38,$00,$00,$00,$00
