; RESET entry.
;
; Sets up the stack, configures ports 1 and 2, and installs the interrupt soft
; vectors before entering the main firmware.
reset:
        LDS     #stackTop               ; stack top - external RAM lies below $0400
        LDAA    #$10
        STAA    PORT1
        CLR     P1DDR
        LDAA    #$11
        STAA    P2DDR
        STAA    PORT2
        LDD     #nullHandler
        STD     >softVecTof
        STD     >softVecIcf
        STD     >softVecSwi
        LDD     #txBitTick
        STD     >softVecOcf
        LDD     #sciRxHandler
        STD     >softVecSci
        LDD     #hostIrq
        STD     >softVecIrq1
        LDD     #$787F
        STAA    PORT4
        STAB    PORT4
        LDAA    #$AB
        STAA    P4DDR
        LDD     #$0395
        STAA    >dbtLatch
        STAB    >dbtLatch
        LDAA    #$08
        STAA    TCSR
        LDD     COUNTH
        ADDD    #$3415
        STD     OCRH
        LDAA    TRCSR
        LDAA    RDR
        LDAA    #$0C
        STAA    RMCR
        LDAA    #$08
        STAA    TRCSR
        LDAA    TRCSR
        LDAA    RDR
        JSR     LEEB1
        JSR     LEE9A
        JSR     LD849
        JSR     drcsClearStore
        JSR     setRowPointers
        JSR     LECCB
        JSR     LB2A3
        JSR     resetStatusLine
        JSR     redrawScreen
        LDD     #$F87F
        STAA    PORT4
        STAB    PORT4
        CLI

LB280:
        SEI
        LDS     #stackTop
        LDD     #sciRxHandler
        STD     >softVecSci
        CLI
        CLR     modeAscii
        CLR     modePrestel
        CLR     modeAntiope
        JSR     LEE9A
        JSR     resetStatusLine
        CLR     pendingByte
        JSR     LED9D
        JMP     parseNextByte

LB2A3:
        LDAA    #$03
        STAA    P1DDR
        LDAA    #$03
        STAA    PORT1
        LDAA    #$0B
        TST     PORT1
        BPL     LB2B4
        LDAA    #$8B

LB2B4:
        STAA    P4DDR
        TPA
        PSHA
        SEI
        STS     scrollEnd               ; scrollEnd is scratch here - nothing scrolls until the payload has been sent
        LDS     #$B32C
        LDX     #$6000

LB2C2:
        PULA
        STAA    $00,X
        INX
        CPX     #$6079
        BCS     LB2C2
        LDS     scrollEnd
        PULA
        TAP
        LDAA    PORT1
        ANDA    #$FE
        STAA    PORT1
        STAA    c64IrqArmB
        STAA    c64IrqArmA
        LDX     #$B3A5
        STX     scrollEnd

; Ship the C64 payload across the dual-port interface.
;
;     LDAA #$FF / STAA c64XferEn      enable transfer
;     TST c64Status (twice)           wait for the C64, double-read for stability
;   loop:
;     LDX $0406 / INX
;     CPX #$D109 / BEQ done           payload ends at $D108
;     LDAA 0,X                        next payload byte
;     LDAB c64FifoWr                  our write index
;     LDX #c64Fifo / ABX              slot = $6080 + index
;     INCB / ANDB #$0F                advance, 16-slot ring
;     CMPB c64FifoRd (twice)          spin while full
;     STAA 0,X / STAB c64FifoWr       store byte, publish index
;     BRA loop
;   done:
;     CLR c64XferEn / wait c64Status / STAA c64XferDone
;
; $0406 is the source pointer, seeded with LDX #$B3A5 at $B2DC; the INX before
; each fetch makes $B3A6 the first byte sent - the two-byte load address the C64
; loader consumes. So $B32D-$B3A5 is NOT streamed: the C64 executes it directly
; from cartridge ROM at $8000. Only $B3A6-$D108 goes through the FIFO.
;
; Both sides guard against metastability the same way, reading a shared index
; twice and acting only when the two reads agree - CMPB c64FifoRd here, and
; LDA $8009 / CMP $8009 / BNE in the C64 bootstrap.
;
; $0406 is a shared scratch pointer, reused at $EA54 and elsewhere for pointer
; tables at $FC45/$FC77/$FCA9/$FCDB.
sendPayloadToC64:
        LDAA    #$FF
        STAA    c64XferEn

LB2E7:
        TST     c64Status
        BEQ     LB2E7
        TST     c64Status
        BEQ     LB2E7

LB2F1:
        LDX     scrollEnd
        INX
        CPX     #ctrlTableC0            ; one past c64Payload's last byte - the address is also where ctrlTableC0 starts
        BEQ     LB31A
        STX     scrollEnd
        LDAA    $00,X

LB2FF:
        LDAB    c64FifoWr
        LDX     #c64Fifo
        ABX
        INCB
        ANDB    #$0F
        CMPB    c64FifoRd
        BEQ     LB2FF
        CMPB    c64FifoRd
        BEQ     LB2FF
        STAA    $00,X
        STAB    c64FifoWr
        BRA     LB2F1

LB31A:
        CLR     c64XferEn

LB31D:
        TST     c64Status
        BNE     LB31D
        TST     c64Status
        BNE     LB31D
        LDAA    #$FF
        STAA    c64XferDone
        RTS

; bootstrap: 6502 code, assembled separately at $8000. See out/c64_bootstrap.asm.
        BINCLUDE "c64_bootstrap.bin"


; payload: 6502 code, assembled separately at $0FFE. See out/c64_payload.asm.
        BINCLUDE "c64_payload.bin"


