        ABX
        CPX     #$5300
        BCS     LEE75
        LDAA    #$07
        LDX     #planeAttr
        LDAA    #$07

LEE84:
        STAA    $02,X
        ABX
        CPX     #$5300
        BCS     LEE84
        LDX     #planeAttr
        LDAA    #$99

LEE91:
        STAA    $03,X
        ABX
        CPX     #$5300
        BCS     LEE91
        RTS

LEE9A:
        JSR     clearPlanes
        CLR     redrawReq
        LDX     #$1B03
        LDAA    #$0F

LEEA5:
        STAA    $00,X
        INX
        CPX     #scrollTop-1
        BNE     LEEA5
        STAA    rowFlags
        RTS

LEEB1:
        LDAA    #$18

LEEB3:
        STAA    PORT3
        LDX     #$5F80
        LDAA    #$02
        LDAB    #$04

LEEBC:
        CLR     $00,X
        CLR     $01,X
        CLR     $02,X
        STAA    $03,X
        ABX
        CPX     #$6000
        BCS     LEEBC
        LDAA    PORT3
        INCA
        CMPA    #$40
