; The default status line, and what a c64StrTable record actually is.
;
; resetStatusLine writes four bytes into every cell of planeAttr's last row -
; $5300 stepping by 4 to $53A0, which is 40 cells:
;
;     byte 0  $00
;     byte 1  $C0
;     byte 2  defaultColour
;     byte 3  $98 AND revealMask
;
; The prompt path at $F22A does the same thing with the first four bytes of the
; record the C64 sent, each written across all 40 cells. So the record header is
; not metadata about the string - it *is* the status line's four attribute
; bytes.
;
; That settles what the varying bytes were: byte 2 is the colour, $07 for white
; or $01 for red, which is exactly what host commands ',' and '.' put in
; defaultColour. A prompt record like msgLoadFile carries $01 and reads red; a
; plain one like msgBlank carries $07.
;
; promptLeft counts the 44 bytes down - four attributes then forty characters -
; and the write column is derived as 40 minus what is left.
resetStatusLine:
        LDAA    modePrestel
        ORAA    modeAntiope
        ORAA    modeAscii
        BNE     LEEFC
        LDX     #$5300
        LDAB    #$04

LEEE2:
        CLR     $00,X
        LDAA    #$C0
        STAA    $01,X
        LDAA    defaultColour
        STAA    $02,X
        LDAA    #$98
        ANDA    revealMask
        STAA    $03,X
        ABX
        CPX     #$53A0
        BCS     LEEE2
        BRA     LEF15

LEEFC:
        LDX     #$5300
        LDAB    #$04

LEF01:
        CLR     $00,X
        LDAA    #$C0
        STAA    $01,X
        LDAA    #$E0
        STAA    $02,X
        LDAA    #$99
        STAA    $03,X
        ABX
        CPX     #$53A0
        BCS     LEF01

LEF15:
        JSR     showModeName
        JSR     showStatusMsg
        RTS

showModeName:
        JSR     cursorBlinkOn
        TPA
        PSHA
        SEI
        STS     savedSP
        LDS     #strModeNames-1
        TST     modeHex
        BEQ     LEF32
        LDS     #strModeNames+79
        BRA     LEF4E

LEF32:
        TST     modePrestel
        BEQ     LEF3C
        LDS     #strModeNames+19
        BRA     LEF4E

LEF3C:
        TST     modeAntiope
        BEQ     LEF46
        LDS     #strModeNames+59
        BRA     LEF4E

LEF46:
        TST     modeAscii
        BEQ     LEF4E
        LDS     #strModeNames+39

LEF4E:
        LDX     #$57C0

LEF51:
        PULA
        ORAA    #$80
        STAA    $00,X
        INX
        CPX     #$57D4
        BCS     LEF51
        LDS     savedSP
        PULA
        TAP
        LDAA    #$FF
        STAA    statusDirty
        RTS

; Terminal mode names, 20 columns each: "CEPT Bildschirmtext", "PRESTEL
; Videotex", "ASCII Terminal-Mode", "ANTIOPE", "HEX-Tastatureingabe".
;
; The decoder therefore speaks more than CEPT - PRESTEL is the British videotex
; variant and ANTIOPE the French one.
strModeNames:
        FCC     "CEPT Bildschirmtext "
        FCC     "PRESTEL Videotex    "
        FCC     "ASCII Terminal-Mode "
        FCC     "ANTIOPE             "
        FCC     "HEX-Tastatureingabe "

showStatusMsg:
