; Status messages, 20 columns each, and the version string.
;
; "Anwahl", "Bitte warten...", "Verbindung", "nicht verbunden", "Abbruch",
; "Decodersoftware V3.3", "Belegt".
;
; The version string is what dates the two ROM revisions against each other:
; this image is V3.3 and CV30113 is V3.1, so this is the newer build. See
; docs/cv30113-revision-diff.md.
strStatusMsgs:
        FCC     "Anwahl              "
        FCC     "Bitte warten...     "
        FCC     "Verbindung          "
        FCC     "nicht verbunden     "
        FCC     "Abbruch             "
        FCC     "Decodersoftware V3.3"
        FCC     "Belegt              "

LF081:
        JSR     fetchHostByte
        JSR     execHostByte
        JSR     rxBufGet
        CMPA    #$00
        BNE     LF0A9
        CLR     statusDirty
        JSR     redrawScreen

LF094:
        JSR     fetchHostByte
        JSR     execHostByte
        LDAA    redrawReq
        ORAA    statusDirty
        BNE     LF081
        JSR     rxBufGet
        CMPA    #$00
        BEQ     LF094

LF0A9:
        TST     captureMode
        BEQ     LF0B1
        JSR     LF979

; pageCount, and why the C64 watches it.
;
; This sits at the end of the receive loop, after a byte has come off the line
; and been forwarded to the C64 if captureMode is on:
;
;     CMPA #$1A / BNE done
;     LDAB pageCount / CMPB pageCount / BNE again    the usual double read
;     INCB / STAB pageCount
;
; So the decoder counts $1A bytes arriving from the line - the end-of-page
; marker in the BTX datastream - and publishes the count where the C64 can see
; it as btxPageCount. c64WaitDecoder spins until it changes, which is how a
; macro waits for the next page before continuing, and c64MacroRecOpen paces the
; macro file against it.
;
; It is the only one of the four registers at $8005, $800F, $8011 and $8012 that
; both processors touch. The other three are C64-side only - the 6801 never
; addresses $6005, $600F or $6012 by any mode.
LF0B1:
        CMPA    #$1A
        BNE     LF0C1

LF0B5:
        LDAB    pageCount
        CMPB    pageCount
        BNE     LF0B5
        INCB
        STAB    pageCount

LF0C1:
        RTS

cursorBlinkOff:
        LDX     blinkTimer
        BMI     LF0F7
        LDX     #$FFFF
        STX     blinkTimer
        LDX     #$5300
        LDD     $02,X
        STD     blinkSave
        LDD     #$0889

LF0D8:
        STD     $02,X
        INX
        INX
        INX
        INX
        CPX     #$53A0
        BCS     LF0D8
        LDX     #$57C0

LF0E6:
        LDAA    $00,X
        ORAA    #$80
        STAA    $00,X
        INX
        CPX     #$57E8
        BCS     LF0E6
        LDAA    #$FF
        STAA    statusDirty

LF0F7:
        RTS

cursorBlinkOn:
        LDX     blinkTimer
        BPL     LF128
        LDX     #$02EE
        STX     blinkTimer
        LDX     #$5300
        LDD     blinkSave

LF109:
        STD     $02,X
        INX
        INX
        INX
        INX
        CPX     #$53A0
        BCS     LF109
        LDX     #$57C0

LF117:
        LDAA    $00,X
        ORAA    #$80
        STAA    $00,X
        INX
        CPX     #$57E8
        BCS     LF117
        LDAA    #$FF
        STAA    statusDirty

LF128:
