; Interrupt soft-vector stubs.
;
; Each stub loads a 16-bit handler address from internal RAM and jumps through
; it, so handlers can be revectored at runtime. Reset installs nullHandler into
; the vectors it does not use.
stubSci:
        LDX     >softVecSci
        JMP     $00,X

stubTof:
        LDX     >softVecTof
        JMP     $00,X

stubOcf:
        LDX     >softVecOcf
        JMP     $00,X

stubIcf:
        LDX     >softVecIcf
        JMP     $00,X

stubIrq1:
        LDX     >softVecIrq1
        JMP     $00,X

stubSwi:
        LDX     >softVecSwi
        JMP     $00,X

nullHandler:
        RTI                             ; null interrupt handler

hostIrq:
        JSR     fetchHostByte
        RTI

; 75-baud transmit: a software UART clocked by the timer output compare.
;
; The BTX line is asymmetric - 1200 baud down, 75 baud up - and the two
; directions are handled by completely different hardware:
;
;   receive   the 6801 SCI, RMCR = $0C (CC1:CC0 = 11, EXTERNAL clock, so the
;             modem supplies the 1200-baud bit clock). TRCSR = $08 enables the
;             receiver only; $F5B4 later raises it to $18 for RE + RIE.
;   transmit  this routine. TRCSR bit 1 (TE) is NEVER set and TDR is never
;             written anywhere in the image, by any addressing mode - the SCI
;             transmitter is entirely unused.
;
; Each output compare reloads OCR with +$3415 (13333 cycles = 75.002 Hz at a
; 1 MHz E clock) and drives one bit by writing TCSR bit 0, which is OLVL - the
; level the compare hardware places on P21. Letting the timer drive the pin
; keeps the bit timing free of interrupt-latency jitter.
;
; Frame: idle -> fetch a byte from the ring at txRing when head != tail, store
; it complemented in txShift, set txBitsLeft = 9, and raise OLVL for the start
; bit. Each later tick shifts the next bit into OLVL; when txBitsLeft reaches 1
; the line is driven low for the stop bit.
;
; With nothing to send the routine falls through to $F1B3, which services
; housekeeping and a countdown at $04CB.
txBitTick:
        LDAA    TCSR
        LDD     OCRH
        ADDD    #$3415
        STD     OCRH
        LDAB    P4DDR
        ANDB    #$0F
        TST     PORT1
        BPL     LF160
        ORAB    #$80

LF160:
        STAB    P4DDR
        LDAA    txBitsLeft
        BNE     LF18A
        LDAB    txRingHead
        CMPB    txRingTail
        BEQ     LF1B3
        LDX     #txRing
        INCB
        ABX
        INC     txRingHead
        LDAA    $00,X
        COMA
        STAA    txShift
        LDAA    #$09
        STAA    txBitsLeft
        LDAA    TCSR
        ORAA    #$01
        STAA    TCSR
        BRA     LF1B0

LF18A:
        CMPA    #$01
        BNE     LF199
        LDAA    TCSR
        ANDA    #$FE
        STAA    TCSR
        DEC     txBitsLeft
        BRA     LF1B0

LF199:
        LDAA    txShift
        ANDA    #$01
        STAA    txCurBit
        LDAA    TCSR
        ANDA    #$FE
        ORAA    txCurBit
        STAA    TCSR
        DEC     txBitsLeft
        LSR     txShift

LF1B0:
        JMP     LF1D7

LF1B3:
        JSR     fetchHostByte
        TST     connected
        BEQ     LF1D7
        TST     blinkOff
        BNE     LF1D7
        TST     revealMask
        BPL     LF1D7
        LDAA    defaultColour
        CMPA    #$07
        BNE     LF1D7
        LDX     blinkTimer
        BEQ     LF1D7
        BMI     LF1D7
        DEX
        STX     blinkTimer

LF1D7:
        RTI

; Take the next byte the C64 sent, if there is one.
;
; pendingByte is the latch between this and execHostByte: TST pendingByte means
; "is one already waiting", STAA pendingByte parks it, and CLR pendingByte is how
; the consumer says it is done. All 14 sites are that one role.
;
;     TPA / PSHA / SEI              run masked, restore CC on the way out
;     TST pendingByte / BEQ         already holding one? nothing to do
;     JSR hostFifoGet               the 64-byte ring at $6040, which the C64
;                                   fills through btxTxFifo at $8040
;     JSR $F459                     SEC / RTS - the second source is a stub, so
;                                   the C64 link is the only one left
;     CMPA #$2C / CMPA #$2E         ',' and '.' set $0494 instead of latching
;     STAA pendingByte
;
; $45 is the code execHostByte and the connect sequences at $F881 and $F8BD all
; test for, which is what makes pendingByte worth following: it is the one byte
; of state between the host link and everything the firmware does about it.
fetchHostByte:
        TPA
        PSHA
        SEI
        TST     pendingByte
        BEQ     LF1E3
        JMP     LF409

LF1E3:
        JSR     hostFifoGet
        BCC     LF1F0
        JSR     LF459
        BCC     LF1F0
        JMP     LF409

LF1F0:
        TST     modeHex
        BEQ     LF22A
        SUBA    #$30
        CMPA    #$09
        BLS     LF20C
        ORAA    #$20
        SUBA    #$27
        CMPA    #$0F
        BLS     LF20C
        CLR     modeHex
        JSR     showModeName
        JMP     LF409

LF20C:
