LF22A:
        LDAB    promptLeft
        BEQ     LF29F
        CMPB    #$28
        BLS     LF253
        LDAB    #$2C
        SUBB    promptLeft
        CMPB    #$03
        BNE     LF23F
        ANDA    revealMask

LF23F:
        LDX     #$5300                  ; each of the first four bytes is written across all 40 cells of the status row
        ABX
        LDAB    #$04

LF245:
        STAA    $00,X
        ABX
        CPX     #$53A0
        BCS     LF245
        DEC     promptLeft
        JMP     LF409

LF253:
        CMPA    #$00
        BNE     LF25D
        CLR     promptLeft
        JMP     LF409

LF25D:
        CMPA    #$09
        BEQ     LF299
        CMPA    #$08
        BNE     LF287
        LDAA    promptLeft
        CMPA    #$28
        BCS     LF26F
        JMP     LF409

LF26F:
