        FDB     planeChar+320,planeChar+360,planeChar+400,planeChar+440,planeChar+480,planeChar+520,planeChar+560,planeChar+600
        FDB     planeChar+640,planeChar+680,planeChar+720,planeChar+760,planeChar+800,planeChar+840,planeChar+880,planeChar+920
        FDB     planeChar+960

lineAddrAttr:
        FDB     planeAttr,planeAttr+160,planeAttr+320,planeAttr+480,planeAttr+640,planeAttr+800,planeAttr+960,planeAttr+1120
        FDB     planeAttr+1280,planeAttr+1440,planeAttr+1600,planeAttr+1760,planeAttr+1920,planeAttr+2080,planeAttr+2240,planeAttr+2400
        FDB     planeAttr+2560,planeAttr+2720,planeAttr+2880,planeAttr+3040,planeAttr+3200,planeAttr+3360,planeAttr+3520,planeAttr+3680
        FDB     planeAttr+3840

; Screen line-address tables: four tables of 25 big-endian pointers, one entry
; per display row, $FC45-$FD0C. 25 rows of 40 columns - the CEPT 24-row page
; plus a status line.
;
;   table  base    stride  span         role
;   $FCDB  $4000     40    $4000-$43C7  rowRender   derived render byte per cell
;   $FCA9  $4400    160    $4400-$539F  rowAttr     four attribute bytes per cell
;   $FC77  $5400     40    $5400-$57C7  rowChar     character codes
;   $FC45  $5800     40    $5800-$5BC7  rowAccent   combining diacritical overlay
;
; $E9A5 reloads all four row pointers into rowChar/rowAttr/rowCharAlt/rowRender
; whenever the cursor row changes. Roles established from the write sites:
;
;   rowChar     $E943 on the main character path:
;               LDAB cursorCol / LDX rowChar / ABX / LDAA charCode / ORAA #$80 /
;               STAA 0,X - the character code with bit 7 set. Bit 7 is a per-cell
;               flag rather than data: $A243, $DB1B, $DB96, $E538 and $EE21 all
;               set it on this plane without touching the low seven bits, so it
;               reads as a dirty/redraw marker.
;   rowAttr     $E7E6 writes attr0..attr3 to 0,X..3,X at cursorCol*4. Those four
;               bytes are only ever bit-manipulated by the C1 handlers at
;               $DE00-$DF10 - the CEPT attribute set - and never receive a raw
;               byte, which is what distinguishes them from the character code.
;   rowRender   $E87E stores a byte assembled at $E860 from attribute bits
;               (BITA #$03 -> ORAB #$02, BITA #$04 -> ORAB #$80, and so on), so
;               this plane is derived state for the display hardware, not
;               content.
;   rowAccent   $E972, reached only when the character is a G2 non-spacing
;               diacritical. Stores charCode AND $7F and sets accentPending.
;
; The second character plane is NOT a duplicate: $5800 is the combining-accent
; overlay. $E91D gates it on two conditions -
;
;     LDAA gSetSelector / CMPA #$01      character came from G2
;     LDAA charCode / ANDA #$70 / CMPA #$40   code in $40-$4F
;
; which is exactly where CEPT G2 puts the non-spacing diacriticals, matching the
; accent glyphs rendered from the $8780 font set. $E972 stores the mark and
; returns WITHOUT advancing the cursor - the defining property of a combining
; character - whereas the normal path at $E94E does INC cursorCol / JSR $EC16.
;
; The sequence is:
;
;   1. a G2 mark $40-$4F arrives: stored in the $5800 plane at the current cell,
;      cursor unmoved, accentPending = $FF;
;   2. the next character arrives: $E8D5 ORs bit 3 of accentPending into that
;      cell's attribute byte, then clears accentPending;
;   3. the base character goes to the $5400 plane and the cursor advances.
;
; The firmware only ever writes $5800 - the sole reads of its row pointer are
; the write at $E972 and the setup at $E9C1 - so the video hardware consumes it,
; compositing the mark from $5800 over the glyph from $5400 with the attribute
; bit as the enable.
lineAddrRender:
        FDB     planeRender,planeRender+40,planeRender+80,planeRender+120,planeRender+160,planeRender+200,planeRender+240,planeRender+280
        FDB     planeRender+320,planeRender+360,planeRender+400,planeRender+440,planeRender+480,planeRender+520,planeRender+560,planeRender+600
        FDB     planeRender+640,planeRender+680,planeRender+720,planeRender+760,planeRender+800,planeRender+840,planeRender+880,planeRender+920
        FDB     planeRender+960
        FCB     $5A,$70,$76,$7F,$6F,$7E,$76,$76,$52,$4C,$56,$46,$5C,$51,$49,$41
        FCB     $49,$47,$5E,$0A

